{
  "root": "main",
  "state": {
    "breakdown": [
      {
        "frequency": "Hourly",
        "gross_amount": "$36.06",
        "calculation_details": "Annual Salary / 2,080 Hours"
      },
      {
        "frequency": "Weekly",
        "gross_amount": "$1,442.31",
        "calculation_details": "Annual Salary / 52 Weeks"
      },
      {
        "frequency": "Bi-Weekly",
        "gross_amount": "$2,884.62",
        "calculation_details": "Annual Salary / 26 Pay Periods"
      },
      {
        "frequency": "Semi-Monthly",
        "gross_amount": "$3,125.00",
        "calculation_details": "Annual Salary / 24 Pay Periods"
      },
      {
        "frequency": "Monthly",
        "gross_amount": "$6,250.00",
        "calculation_details": "Annual Salary / 12 Months"
      }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "title",
        "summary_card",
        "context_section",
        "breakdown_section",
        "actions_section"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Salary Conversion Overview",
        "variant": "h1"
      },
      "children": []
    },
    "summary_card": {
      "type": "Card",
      "props": {
        "padding": 16
      },
      "children": [
        "summary_stack"
      ]
    },
    "summary_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "summary_icon",
        "summary_text"
      ]
    },
    "summary_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_001374_01_2_cash-coin.svg"
      },
      "children": []
    },
    "summary_text": {
      "type": "Text",
      "props": {
        "text": "Based on an annual salary of $75,000, your pre-tax hourly wage is approximately $36.06. This calculation assumes a standard full-time schedule without unpaid time off."
      },
      "children": []
    },
    "context_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "context_title",
        "context_body",
        "context_list"
      ]
    },
    "context_title": {
      "type": "Text",
      "props": {
        "text": "Calculation Context",
        "variant": "h2"
      },
      "children": []
    },
    "context_body": {
      "type": "Text",
      "props": {
        "text": "The conversion uses the specific figures provided in your query to determine the gross hourly rate."
      },
      "children": []
    },
    "context_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "paddingHorizontal": 16
      },
      "children": [
        "context_item_1",
        "context_item_2"
      ]
    },
    "context_item_1": {
      "type": "Text",
      "props": {
        "text": "• Total Work Hours: 2,080 hours per year (40 hours x 52 weeks)"
      },
      "children": []
    },
    "context_item_2": {
      "type": "Text",
      "props": {
        "text": "• Pay Frequency: The breakdown below illustrates how this salary translates across different pay periods before taxes or deductions are applied."
      },
      "children": []
    },
    "breakdown_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "breakdown_title",
        "breakdown_table"
      ]
    },
    "breakdown_title": {
      "type": "Text",
      "props": {
        "text": "Gross Income Breakdown",
        "variant": "h2"
      },
      "children": []
    },
    "breakdown_table": {
      "type": "Table",
      "props": {
        "statePath": "/breakdown",
        "columns": [
          {
            "key": "frequency",
            "label": "Frequency"
          },
          {
            "key": "gross_amount",
            "label": "Gross Amount"
          },
          {
            "key": "calculation_details",
            "label": "Calculation Details"
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "sourceFormat": "markdown",
        "sourceText": "Frequency | Gross Amount | Calculation Details\nHourly | $36.06 | Annual Salary / 2,080 Hours\nWeekly | $1,442.31 | Annual Salary / 52 Weeks\nBi-Weekly | $2,884.62 | Annual Salary / 26 Pay Periods\nSemi-Monthly | $3,125.00 | Annual Salary / 24 Pay Periods\nMonthly | $6,250.00 | Annual Salary / 12 Months"
      },
      "children": []
    },
    "actions_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "actions_title",
        "actions_buttons"
      ]
    },
    "actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "actions_buttons": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "align": "start"
      },
      "children": [
        "action_1_stack",
        "action_2_button"
      ]
    },
    "action_1_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "action_1_icon",
        "action_1_button"
      ]
    },
    "action_1_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_001374_01_1_calculator.svg"
      },
      "children": []
    },
    "action_1_button": {
      "type": "Button",
      "props": {
        "label": "Calculate Take-Home Pay",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.paycheckcity.com/calculator/salary"
          }
        }
      }
    },
    "action_2_button": {
      "type": "Button",
      "props": {
        "label": "Bureau of Labor Statistics Wage Data",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bls.gov/bls/blswage.htm"
          }
        }
      }
    }
  }
}
